#!/usr/bin/env node
/* --check mode (added 2026-08-27): report whether the generated files still
 * match wordmap_meta.js instead of writing them. This is the largest generated
 * set in the repo — wordmap_meta_lite.js, meta_desc/ (11 MB) and meta_i18n/
 * (5.8 MB) — and until now nothing guarded it. Editing wordmap_meta.js without
 * rerunning left the site serving the old metadata; the only thing that noticed
 * was the content-hash version lock, which is routinely --updated. */
/*
 * build_meta_split.js — split the 19 MB wordmap_meta.js so a language popup
 * no longer pulls the whole corpus.
 *
 * wordmap_meta.js is ~19 MB: per-language LANG_DATA[code].meta (11.6 MB, of
 * which .description + .sources are 11.35 MB) PLUS the base META_I18N table.
 * loadMeta() pulled all of it on the first popup (4 min on slow 4G).
 *
 * This emits:
 *   - wordmap_meta_lite.js  : LANG_DATA[code].meta with ONLY the small
 *                             structured fields (family/speakers/script/period/
 *                             …), every language, ~0.27 MB. Loaded by loadMeta()
 *                             for the filter / games / historical view / popup.
 *   - meta_desc/<code>.js   : that one language's .description + .sources
 *                             (~10 KB), Object.assign-merged onto its .meta.
 *                             Loaded only when that language's popup opens.
 *
 * The base META_I18N table stays in wordmap_meta.js for now (Stage 2 splits it
 * per-UI). Run from repo root:  node tools/build_meta_split.js
 */
const fs = require('fs');
const path = require('path');

// --check: stage every write and diff it, so one run answers "is any of this stale?"
const CHECK = process.argv.includes('--check');
let STALE = 0;
const _write = fs.writeFileSync.bind(fs);
const _mkdir = fs.mkdirSync.bind(fs);
if (CHECK) {
    fs.writeFileSync = (p, body) => {
        const cur = fs.existsSync(p) ? fs.readFileSync(p, 'utf8') : null;
        if (cur !== String(body)) STALE++;
    };
    fs.mkdirSync = () => {};
    const seen = new Set();
    process.on('exit', () => {
        console.log(`stale: ${STALE}`);
        if (STALE) console.log('  run: node tools/build_meta_split.js');
    });
}
const vm = require('vm');
const ROOT = path.join(__dirname, '..');

// Fields that are small + needed broadly (map/filter/games/historical). Anything
// NOT here (description, sources) goes to the per-language file.
const LITE_FIELDS = new Set(['family', 'speakers', 'countries', 'official', 'script',
  'scriptTags', 'dataStatus', 'codeType', 'iso6393', 'vitality', 'textDirection',
  'speakerCount', 'parentCode', 'speakerBasis', 'speakerSource', 'speakerYear',
  'glottocode', 'locationBasis', 'pronunciationType', 'surfaceType', 'aliases',
  'reviewStatus', 'coverage', 'baseLang', 'varietyRole', 'languageKind', 'period',
  'disambiguator', 'coverageNote', 'unattestedReason', 'wordsNote', 'extinct',
  'extinctionDate', 'lastSpeaker']);
const DESC_FIELDS = ['description', 'sources']; // the big ones → per-language

const ctx = { window: {}, console };
vm.createContext(ctx);
vm.runInContext(fs.readFileSync(path.join(ROOT, 'wordmap_data.js'), 'utf8') + '\n;this.LANG_DATA=LANG_DATA;', ctx);
vm.runInContext(fs.readFileSync(path.join(ROOT, 'wordmap_meta.js'), 'utf8') +
  '\n;this.META_I18N=(typeof META_I18N!=="undefined")?META_I18N:null;', ctx);
const LD = ctx.LANG_DATA;
const BASE_I18N = ctx.META_I18N; // ~0.35 MB base translation table (was inside wordmap_meta.js)
const codes = Object.keys(LD).filter(c => LD[c] && LD[c].meta);

const q = s => JSON.stringify(s);
// wordmap_meta_lite.js
let lite = '/* wordmap_meta_lite.js — GENERATED by tools/build_meta_split.js.\n' +
  ' * Structured per-language meta only (no description/sources). Drop-in for\n' +
  ' * loadMeta(): sets LANG_DATA[code].meta and fires the same load signal. */\n';
let liteBytes = 0;
const descDir = path.join(ROOT, 'meta_desc');
fs.mkdirSync(descDir, { recursive: true });
let descCount = 0, descBytes = 0;
for (const c of codes) {
  const m = LD[c].meta;
  const small = {}; for (const k of Object.keys(m)) if (LITE_FIELDS.has(k)) small[k] = m[k];
  lite += `(LANG_DATA[${q(c)}]=LANG_DATA[${q(c)}]||{}).meta=Object.assign(LANG_DATA[${q(c)}].meta||{},${JSON.stringify(small)});\n`;
  const big = {}; for (const k of DESC_FIELDS) if (m[k] !== undefined) big[k] = m[k];
  if (Object.keys(big).length) {
    const body = `(LANG_DATA[${q(c)}]=LANG_DATA[${q(c)}]||{}).meta=Object.assign(LANG_DATA[${q(c)}].meta||{},${JSON.stringify(big)});\n`;
    fs.writeFileSync(path.join(descDir, c + '.js'), body);
    descCount++; descBytes += body.length;
  }
}
// The base translation table (translateMetaSmart reads global META_I18N). It
// lived inside wordmap_meta.js; at ~0.35 MB it rides along in the lite file so
// non-English UIs keep their meta translations. Declared exactly as the original
// (top-level const → shared across <script> tags), so meta_i18n_ext.js augments it.
if (BASE_I18N) lite += `const META_I18N = ${JSON.stringify(BASE_I18N)};\n`;
// Same completion signal wordmap_meta.js emits, so loadMeta()'s promise resolves.
lite += 'window._wmMetaLoaded = true;\nif (window._wmMetaResolve) window._wmMetaResolve();\n';
fs.writeFileSync(path.join(ROOT, 'wordmap_meta_lite.js'), lite);
liteBytes = lite.length;
console.error(`wordmap_meta_lite.js: ${(liteBytes / 1024).toFixed(0)} KB (${codes.length} langs)`);
console.error(`meta_desc/: ${descCount} files, ${(descBytes / 1024 / 1024).toFixed(2)} MB total, ${(descBytes / 1024 / descCount).toFixed(1)} KB avg`);

// ===========================================================================
// Stage 2 — split the meta-i18n layer per UI language.
//
// meta_i18n_ext.js (+coverage{,2,3}.js) is ~5.1 MB and holds translations for
// ALL 22 UI languages; a ja user pulled every other UI's strings too. Split into:
//   - meta_i18n_engine.js       : the pure translateMetaSmart engine (functions
//                                 only; ext.js lines 1..N before the data block)
//   - meta_i18n/<ui>.js         : the FINAL merged META_I18N + META_I18N_ATOMS
//                                 for one UI (ja ≈ 253 KB; en ≈ 0). Loaded for
//                                 the current UI only.
// Run all four source files in the VM so the atoms are fully merged, then emit
// the finished per-UI slices — no merge logic needs to ship to the browser.
for (const f of ['meta_i18n_ext.js', 'meta_i18n_coverage.js', 'meta_i18n_coverage2.js', 'meta_i18n_coverage3.js']) {
  vm.runInContext(fs.readFileSync(path.join(ROOT, f), 'utf8'), ctx, { filename: f });
}
vm.runInContext('this.__MI = (typeof META_I18N!=="undefined")?META_I18N:{};' +
  'this.__AT = (typeof META_I18N_ATOMS!=="undefined")?META_I18N_ATOMS:{};', ctx);
const MI = ctx.__MI, AT = ctx.__AT;

// Engine = everything in meta_i18n_ext.js before the `const META_I18N_ATOMS` data
// block. translateMetaSmart + helpers are all there; they read META_I18N (const,
// from the lite file) and META_I18N_ATOMS (created below) by name at call time.
const extSrc = fs.readFileSync(path.join(ROOT, 'meta_i18n_ext.js'), 'utf8').split('\n');
const dataLine = extSrc.findIndex(l => /^const META_I18N_ATOMS\s*=/.test(l));
if (dataLine < 0) throw new Error('could not find META_I18N_ATOMS data boundary in meta_i18n_ext.js');
let engine = extSrc.slice(0, dataLine).join('\n').replace(/\s*$/, '\n');
engine = '/* meta_i18n_engine.js — GENERATED by tools/build_meta_split.js.\n' +
  ' * The translateMetaSmart engine (functions only) sliced out of\n' +
  ' * meta_i18n_ext.js. The per-UI data it reads (META_I18N / META_I18N_ATOMS)\n' +
  ' * comes from wordmap_meta_lite.js + meta_i18n/<ui>.js. DO NOT EDIT — edit\n' +
  ' * meta_i18n_ext.js and regenerate. */\n' + engine +
  '\n// META_I18N_ATOMS is filled per-UI by meta_i18n/<ui>.js; create the global\n' +
  '// here so translateMetaSmart\'s bare reference resolves before that loads.\n' +
  'if (typeof window !== "undefined" && typeof window.META_I18N_ATOMS === "undefined") window.META_I18N_ATOMS = {};\n' +
  'if (typeof window !== "undefined") window.translateMetaSmart = translateMetaSmart;\n';
fs.writeFileSync(path.join(ROOT, 'meta_i18n_engine.js'), engine);
console.error(`meta_i18n_engine.js: ${(engine.length / 1024).toFixed(1)} KB`);

const i18nDir = path.join(ROOT, 'meta_i18n');
fs.mkdirSync(i18nDir, { recursive: true });
const uis = Array.from(new Set([...Object.keys(MI), ...Object.keys(AT)]));
let uiCount = 0, uiBytes = 0;
for (const ui of uis) {
  if (ui === 'en') continue; // English is the source text — translateMetaSmart short-circuits
  const mi = MI[ui] || {}, at = AT[ui] || {};
  if (!Object.keys(mi).length && !Object.keys(at).length) continue;
  // META_I18N is a const from the lite file → augment it by bare name. ATOMS is
  // created by the engine on window → augment window.META_I18N_ATOMS.
  const body = `/* meta_i18n/${ui}.js — GENERATED by tools/build_meta_split.js.\n` +
    ` * Final merged translation data for UI="${ui}". DO NOT EDIT — regenerate. */\n` +
    `(function(){\n` +
    `  if (typeof META_I18N !== "undefined") META_I18N[${q(ui)}] = Object.assign(META_I18N[${q(ui)}]||{}, ${JSON.stringify(mi)});\n` +
    `  var A = (typeof window!=="undefined") ? (window.META_I18N_ATOMS = window.META_I18N_ATOMS||{}) : {};\n` +
    `  A[${q(ui)}] = Object.assign(A[${q(ui)}]||{}, ${JSON.stringify(at)});\n` +
    `})();\n`;
  fs.writeFileSync(path.join(i18nDir, ui + '.js'), body);
  uiCount++; uiBytes += body.length;
}
console.error(`meta_i18n/: ${uiCount} UI files, ${(uiBytes / 1024 / 1024).toFixed(2)} MB total; ja=${((fs.existsSync(path.join(i18nDir,'ja.js'))?fs.statSync(path.join(i18nDir,'ja.js')).size:0)/1024).toFixed(0)}KB`);
